  [skp-intentions-152] "Enforcing Financial Chokepoint Obligations Against Nonconsensual Deepfake Ecosystems"
  [skp-intentions-170] "Enforcing Cryptographic Provenance and Ephemeral Credentials on Commercial Model Registries"
  [skp-intentions-151] "Enforcing Financial Chokepoint Obligations Against Nonconsensual Deepfake Ecosystems"
